#!/usr/bin/env node
/**
 * 停服状态下：将 pending/running 的 session_commit 任务标为 cancelled（UTF-8 无 BOM）
 * 依据 ~/.openviking 内 openviking_import_deadlock_recovery 记忆
 */
import fs from "fs";
import path from "path";
import os from "os";

const TASK_DIR = path.join(
  os.homedir(),
  ".openviking/data/viking/default/_system/tasks/default"
);
const DRY = process.argv.includes("--dry");
const now = Date.now() / 1000;

let changed = 0;
let scanned = 0;
for (const f of fs.readdirSync(TASK_DIR).filter((x) => x.endsWith(".json"))) {
  const fp = path.join(TASK_DIR, f);
  let j;
  try {
    j = JSON.parse(fs.readFileSync(fp, "utf8"));
  } catch {
    continue;
  }
  scanned++;
  if (j.task_type !== "session_commit") continue;
  if (!["pending", "running"].includes(j.status)) continue;
  if (DRY) {
    console.log("would cancel", j.task_id?.slice(0, 8), j.status, j.resource_id?.slice(0, 36));
    changed++;
    continue;
  }
  j.status = "cancelled";
  j.updated_at = now;
  j.stage = "cancelled";
  j.error = j.error || "cancelled for import recovery";
  const body = JSON.stringify(j);
  fs.writeFileSync(fp, body, { encoding: "utf8" });
  const head = fs.readFileSync(fp).subarray(0, 3);
  if (head[0] !== 0x7b) throw new Error("bad file head " + fp);
  changed++;
}
console.log(JSON.stringify({ scanned, cancelled: changed, dry: DRY }, null, 2));

